import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_gn_cuda_code = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cmath>

#define M_SQRT1_2 0.70710678118654752440f

__device__ float gelu(float x) {
    return 0.5f * x * (1.0f + erff(x * M_SQRT1_2));
}

__global__ void fused_gelu_groupnorm_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int channels,
    const int height,
    const int width,
    const int num_groups,
    const float epsilon) {

    const int n = blockIdx.x;
    const int g = blockIdx.y;
    const int group_size = channels / num_groups;
    const int c_start = g * group_size;
    const int c_end = c_start + group_size;
    const int elements_per_group = group_size * height * width;

    extern __shared__ float smem[];
    float* sum = smem;
    float* sum_sq = &smem[blockDim.x];

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    // First pass: compute sum and sum_sq
    for (int idx = threadIdx.x; idx < elements_per_group; idx += blockDim.x) {
        const int c = c_start + (idx / (height * width));
        const int hw = idx % (height * width);
        const int h = hw / width;
        const int w = hw % width;
        const int in_idx = ((n * channels + c) * height + h) * width + w;

        float val = input[in_idx];
        float gelu_val = gelu(val);
        thread_sum += gelu_val;
        thread_sum_sq += gelu_val * gelu_val;
    }

    sum[threadIdx.x] = thread_sum;
    sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads();

    // Block reduction for sum and sum_sq
    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
            sum[threadIdx.x] += sum[threadIdx.x + s];
            sum_sq[threadIdx.x] += sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    const float mean = sum[0] / elements_per_group;
    const float var = sum_sq[0] / elements_per_group - mean * mean;
    const float inv_std = rsqrtf(var + epsilon);

    // Second pass: normalize and apply affine
    for (int idx = threadIdx.x; idx < elements_per_group; idx += blockDim.x) {
        const int c = c_start + (idx / (height * width));
        const int hw = idx % (height * width);
        const int h = hw / width;
        const int w = hw % width;
        const int in_idx = ((n * channels + c) * height + h) * width + w;

        float val = input[in_idx];
        float gelu_val = gelu(val);
        float norm = (gelu_val - mean) * inv_std;
        output[in_idx] = norm * weight[c] + bias[c];
    }
}

torch::Tensor fused_gelu_groupnorm_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int num_groups,
    float epsilon) {

    auto output = torch::empty_like(input);
    const int batch_size = input.size(0);
    const int channels = input.size(1);
    const int height = input.size(2);
    const int width = input.size(3);

    dim3 grid(batch_size, num_groups);
    dim3 block(256);
    size_t smem_size = 2 * block.x * sizeof(float);

    fused_gelu_groupnorm_kernel<<<grid, block, smem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        height,
        width,
        num_groups,
        epsilon);

    return output;
}
